import{_ as e,o as s,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Especificaciones de diseño","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/index.md","filePath":"es/game-design/index.md"}'),o={name:"es/game-design/index.md"};function r(t,a,l,c,d,m){return s(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="design-specs" tabindex="-1">Especificaciones de diseño <a class="header-anchor" href="#design-specs" aria-label="Enlace permanente a &quot;Especificaciones de diseño&quot;">​</a></h1><p>Diseño canónico detallado de Syrolands, que conserva la identidad técnica SyroUO. Cada página distingue intención aceptada, política experimental, propuestas y preguntas abiertas. La documentación canónica no es una autorización general de implementación.</p><p>Para una introducción breve, empezar por la <a href="/Syrolands-Public/es/guide/">Guía del jugador</a>. Cada guía enlaza a su especificación detallada; las etiquetas de estado distinguen la intención de diseño de las funciones disponibles.</p><h2 id="foundations" tabindex="-1">Fundamentos <a class="header-anchor" href="#foundations" aria-label="Enlace permanente a &quot;Fundamentos&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/vision.html">Visión del proyecto</a>.</p><h2 id="characters" tabindex="-1">Personajes <a class="header-anchor" href="#characters" aria-label="Enlace permanente a &quot;Personajes&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/characters/progression.html">Progresión del personaje</a> · <a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html">Habilidades y límite, incluidos maestros</a> · <a href="/Syrolands-Public/es/game-design/characters/techniques-and-specialization.html">Técnicas y especialización</a> · <a href="/Syrolands-Public/es/game-design/characters/character-creation.html">Creación de personajes y orígenes</a> · <a href="/Syrolands-Public/es/game-design/characters/stats.html">Estadísticas</a> — Propuesto.</p><p>Las <a href="/Syrolands-Public/es/game-design/skills-and-knowledge.html">funciones existentes de habilidades de combate y conocimiento</a> conservan sus distinciones Aceptado/Experimental. Falta conciliar la compatibilidad con el comportamiento heredado.</p><h2 id="combat" tabindex="-1">Combate <a class="header-anchor" href="#combat" aria-label="Enlace permanente a &quot;Combate&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/combat/overview.html">Fundamentos del combate</a> · <a href="/Syrolands-Public/es/guide/combat/overview.html">Resumen para jugadores</a>.</p><p><a href="/Syrolands-Public/es/game-design/combat/body-regions.html">Regiones corporales</a> · <a href="/Syrolands-Public/es/game-design/combat/damage.html">Daño y Local Trauma</a> · <a href="/Syrolands-Public/es/game-design/combat/targeting.html">Selección de objetivos y evaluación</a> · <a href="/Syrolands-Public/es/game-design/combat/disability.html">Discapacidad y uso del escudo</a> · <a href="/Syrolands-Public/es/game-design/combat/future-directions.html">Direcciones futuras del combate</a>.</p><p><a href="/Syrolands-Public/es/game-design/combat/weapons-and-damage.html">Armas y familias de daño</a> · <a href="/Syrolands-Public/es/game-design/combat/armor-and-mitigation.html">Armadura y mitigación</a> · <a href="/Syrolands-Public/es/game-design/combat/stamina-and-reactive-combat.html">Stamina y recuperación</a> · <a href="/Syrolands-Public/es/game-design/combat/status-and-open-questions.html">Estado del combate y preguntas abiertas</a>.</p><h2 id="magic" tabindex="-1">Magia <a class="header-anchor" href="#magic" aria-label="Enlace permanente a &quot;Magia&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/magic.html">Resumen de magia</a> · <a href="/Syrolands-Public/es/game-design/magic/spell-knowledge.html">Conocimiento de hechizos y Core Patterns</a> · <a href="/Syrolands-Public/es/game-design/magic/variants-and-glyphs.html">Variantes y glifos</a> · <a href="/Syrolands-Public/es/game-design/magic/memory-and-familiarity.html">Familiarity y Active Memory</a> · <a href="/Syrolands-Public/es/game-design/magic.html#meditation-and-concentration">Meditation y Concentration</a> · <a href="/Syrolands-Public/es/game-design/magic/spellbooks-scrolls-and-reagents.html">Libros de hechizos, pergaminos y reactivos</a> · <a href="/Syrolands-Public/es/game-design/magic/presentation.html">Presentación mágica / VFX</a> · <a href="/Syrolands-Public/es/game-design/magic/status-and-open-questions.html">Estado de la magia y preguntas abiertas</a> — Propuesto, con preguntas sin resolver explícitas. <a href="/Syrolands-Public/es/guide/magic/overview.html">Resumen para jugadores</a>.</p><h2 id="professions" tabindex="-1">Profesiones <a class="header-anchor" href="#professions" aria-label="Enlace permanente a &quot;Profesiones&quot;">​</a></h2><p>El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a> define descubrimiento artesanal, diarios, producción, reputación y conciliación con estado Propuesto, con enlaces al marco compartido del personaje.</p><p><a href="/Syrolands-Public/es/game-design/professions/cooking.html">Cooking</a> · <a href="/Syrolands-Public/es/game-design/professions/alchemy.html">Alchemy</a> · <a href="/Syrolands-Public/es/game-design/professions/mining.html">Mining</a> · <a href="/Syrolands-Public/es/game-design/professions/blacksmithing.html">Blacksmithing</a> · <a href="/Syrolands-Public/es/game-design/professions/tailoring.html">Tailoring</a> · <a href="/Syrolands-Public/es/game-design/professions/lumberjacking.html">Lumberjacking</a> · <a href="/Syrolands-Public/es/game-design/professions/carpentry.html">Carpentry</a> · <a href="/Syrolands-Public/es/game-design/professions/tinkering.html">Tinkering</a> · <a href="/Syrolands-Public/es/game-design/professions/inscription.html">Inscription</a>. <a href="/Syrolands-Public/es/game-design/professions/carpentry.html#bowmaking-and-fletching">Bowmaking / Fletching</a> es un camino técnico, no una habilidad adicional en esta propuesta.</p><h2 id="world" tabindex="-1">Mundo <a class="header-anchor" href="#world" aria-label="Enlace permanente a &quot;Mundo&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/living-world.html">Mundo vivo y materiales</a> — Propuesto. <a href="/Syrolands-Public/es/game-design/creatures.html">Criaturas y anatomía</a>.</p><h2 id="items" tabindex="-1">Objetos <a class="header-anchor" href="#items" aria-label="Enlace permanente a &quot;Objetos&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/equipment-and-loot.html">Equipo y botín</a> · <a href="/Syrolands-Public/es/game-design/items/itemization-and-craft-quality.html">Objetos y calidad artesanal</a> — Propuesto para categorías, rangos posibles, rasgos y propiedades latentes.</p><h2 id="future-coverage" tabindex="-1">Cobertura futura <a class="header-anchor" href="#future-coverage" aria-label="Enlace permanente a &quot;Cobertura futura&quot;">​</a></h2><p>Sociedad / Economía tendrá su propio grupo cuando exista contenido sustancial separado. Los encargos profesionales y la reputación pertenecen actualmente al <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#commissions-reputation-and-economy">Sistema de profesiones</a>. La cobertura adicional conservará las mismas distinciones de estado.</p><h2 id="combat-actions-and-practice-—-proposed" tabindex="-1">Acciones de combate y práctica — Propuesto <a class="header-anchor" href="#combat-actions-and-practice-—-proposed" aria-label="Enlace permanente a &quot;Acciones de combate y práctica — Propuesto&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/combat/legacy-and-modern.html">Legacy y Modern</a> · <a href="/Syrolands-Public/es/game-design/combat/actions.html">Special Attacks</a> · <a href="/Syrolands-Public/es/game-design/combat/flow.html">Flow</a> · <a href="/Syrolands-Public/es/game-design/combat/reach-and-spacing.html">Alcance y distancia</a> · <a href="/Syrolands-Public/es/game-design/characters/familiarity.html">Familiarity</a>.</p><p>El <a href="/Syrolands-Public/es/game-design/combat/variable-registry.html">Registro de variables de combate</a> reúne definiciones antes del ajuste numérico; no se establece que ningún modo ni acción nuevos sean jugables.</p><h2 id="three-weapon-test-profile" tabindex="-1">Perfil de prueba de tres armas <a class="header-anchor" href="#three-weapon-test-profile" aria-label="Enlace permanente a &quot;Perfil de prueba de tres armas&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/combat/numeric-prototype.html">Longsword, Spear y War Hammer</a> ya tienen cifras de estado Experimental para un prototipo futuro. No están implementadas ni son balance definitivo.</p><p><a href="/Syrolands-Public/es/guide/glossary.html">El glosario del jugador</a> define los términos compartidos que utilizan estas especificaciones.</p>',29)])])}const u=e(o,[["render",r]]);export{h as __pageData,u as default};
